css:
.billing-run-print {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    color: #333;
    padding: 10px;
}

.print-header {
    border-bottom: 2px solid #1F497D;
    padding-bottom: 15px;
    margin-bottom: 25px;
}

.print-header h2 {
    color: #1F497D;
    margin-top: 0;
    margin-bottom: 10px;
    font-weight: bold;
}

.total-highlight {
    font-size: 18px;
    font-weight: bold;
    color: #1F497D;
}

.print-section {
    margin-bottom: 35px;
}

.print-section h3 {
    color: #1F497D;
    font-size: 16px;
    border-bottom: 1px solid #ddd;
    padding-bottom: 5px;
    margin-bottom: 15px;
    font-weight: bold;
}

.table {
    width: 100%;
    margin-bottom: 20px;
    border-collapse: collapse;
}

.table-bordered th, .table-bordered td {
    border: 1px solid #ddd !important;
    padding: 8px !important;
    vertical-align: middle !important;
}

.table th {
    background-color: #f5f5f5;
    font-weight: bold;
    color: #1F497D;
}

.font-bold {
    font-weight: bold;
}

.text-right {
    text-align: right;
}

.total-row {
    background-color: #fcfcfc;
}

.total-row td {
    border-top: 1.5px solid #1F497D !important;
    border-bottom: 3px double #1F497D !important;
    font-size: 14px;
}

@media print {
    .page-break-before {
        page-break-before: always;
    }
}
